SELECT
coalesce(SUM(refund_amount*dri.currency_rate),0)
FROM dmp_refund_info dri
INNER JOIN dmp_order_info o
ON dri.platform_order_id=o.platform_order_id
WHERE   dri.refund_status=4

    AND dri.refund_time >= #{params.startTime}


    AND dri.refund_time < #{params.endTime}



    AND o.source_platform IN

        #{platform}




    AND o.shop_name IN

        #{shopName}




    AND o.dept_id IN

        #{deptId}




    AND o.charge_id IN

        #{userId}




    ${params.permissionSql}

SELECT
coalesce(SUM(refund_amount*dri.currency_rate),0)
FROM dmp_refund_info dri
INNER JOIN
(
SELECT o.platform_order_id FROM
dmp_order_info o INNER JOIN dmp_order_item i
ON i.order_id = o.ID


        EXTRACT( YEAR FROM o.platform_create_time )=${year}



        EXTRACT( YEAR FROM o.delivery_time )=${year}



        AND o.dept_id IN

            #{deptId}




        AND o.source_platform IN

            #{platform}




        AND o.site IN

            #{site}




        AND o.shop_name IN

            #{shopName}




        AND i.sku_no IN

            #{sku}




        AND i.sku_no IN
        ( SELECT sku_no FROM product_detail pd INNER JOIN product_info pi ON pi.id=pd.product_id WHERE
        pi.category_id IN

            #{category}

        )



        AND i.sku_no IN
        ( SELECT sku_no FROM product_detail pd INNER JOIN product_info pi ON pi.id=pd.product_id WHERE
        pi.brand_name IN

            #{brand}

        )



        AND o.charge_id IN

            #{userId}




        ${params.permissionSql}


GROUP BY O.id
) temp
ON temp.platform_order_id=dri.platform_order_id
